import React from 'react';
import { Button, InlineLabel, Input, PaginationBar, SearchInput, Stack } from '@oods/components-react';
import '@oods/component-styles/css';

export interface PageProps {
  /** Chunk index. */
  chunkIndex: number;
  /** Content. */
  content: string;
  /** Created at. */
  createdAt: string;
  /** Supporting description used in detail and card contexts. */
  description?: string;
  /** Document id. */
  documentId: string;
  /** Embedding id. */
  embeddingId?: string;
  /** End char. */
  endChar?: number;
  /** Id. */
  id: string;
  /** Display projection of content; retain the complete source field. */
  label: string;
  /** Next chunk id. */
  nextChunkId?: string;
  /** Hint copy surfaced in form fields when the label is empty. */
  placeholder?: string;
  /** Prev chunk id. */
  prevChunkId?: string;
  /** Start char. */
  startChar?: number;
  /** Token count. */
  tokenCount?: number;
}

type ButtonProps = React.ComponentPropsWithoutRef<typeof Button>;
type InlineLabelProps = React.ComponentPropsWithoutRef<typeof InlineLabel>;
type InputProps = React.ComponentPropsWithoutRef<typeof Input>;
type PaginationBarProps = React.ComponentPropsWithoutRef<typeof PaginationBar>;
type SearchInputProps = React.ComponentPropsWithoutRef<typeof SearchInput>;
type StackProps = React.ComponentPropsWithoutRef<typeof Stack>;

export const GeneratedUI: React.FC<PageProps> = ({ chunkIndex, content, createdAt, description, documentId, embeddingId, endChar, id, label, nextChunkId, placeholder, prevChunkId, startChar, tokenCount }) => {
  const [handleChange_chunk_indexState, setHandleChange_chunk_indexState] = React.useState<string>(String(chunkIndex ?? ''));
  /* @oods-local-binding handleChange_chunk_index */ const handleChange_chunk_index = (event: React.ChangeEvent<HTMLInputElement>) => { setHandleChange_chunk_indexState(event.currentTarget.value); };
  const [handleUpdate_embedding_idState, setHandleUpdate_embedding_idState] = React.useState<string>(String(embeddingId ?? ''));
  /* @oods-local-binding handleUpdate_embedding_id */ const handleUpdate_embedding_id = (value: string) => { setHandleUpdate_embedding_idState(value); };

  return (
    <>
      <Stack id="screen-list-9" data-oods-component="Stack" data-layout="stack" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--ref-space-cluster-default)' }}>
            <Stack id="list-toolbar-4" data-oods-component="Stack" data-layout="inline" style={{ display: 'flex', flexDirection: 'row', justifyContent: 'space-between', padding: 'var(--ref-space-inset-default)' }}>
                    <SearchInput id="slot-search-1" data-oods-component="SearchInput" label="Embedding id" placeholder="Enter embedding id" value={handleUpdate_embedding_idState} onUpdate={handleUpdate_embedding_id} />
                    <Input id="slot-filters-2" data-oods-component="Input" label="Chunk index" placeholder="Enter chunk index" required type="number" value={handleChange_chunk_indexState} onChange={handleChange_chunk_index} />
                    <Button id="slot-toolbar-actions-3" data-oods-component="Button" />
                  </Stack>
            <Stack id="list-items-5" data-oods-component="Stack" data-layout="stack" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--ref-space-cluster-tight)' }}>
                    <InlineLabel id="slot-items-6" data-oods-component="InlineLabel" maxLength={40} label={label} />
                  </Stack>
            <Stack id="list-pagination-7" data-oods-component="Stack" data-layout="inline" style={{ display: 'flex', flexDirection: 'row', justifyContent: 'center', padding: 'var(--ref-space-inset-default)' }}>
                    <PaginationBar id="slot-pagination-8" data-oods-component="PaginationBar" />
                  </Stack>
          </Stack>
    </>
  );
};
